package main

import (
	"fmt"
	"goa.design/goa/v3/codegen"
)

func main() {
	// Simulate what happens with an error type in a custom package

	// Before the fix:
	// The code would manually check for "struct:pkg:path" metadata and use path.Base
	// This would give us just the base package name but wouldn't work consistently

	// After the fix:
	// We use pkgWithDefault(errorLoc, svc.PkgName) which is consistent with how
	// payloads and results are handled

	loc := &codegen.Location{
		FilePath:      "/path/to/custom/error.go",
		RelImportPath: "custom",
	}

	pkgName := loc.PackageName()
	fmt.Printf("Package name from location: %s\n", pkgName)

	// When loc is nil (no custom package), pkgWithDefault returns the default
	var nilLoc *codegen.Location
	defaultPkg := "myservice"
	result := pkgWithDefault(nilLoc, defaultPkg)
	fmt.Printf("Package name when loc is nil: %s\n", result)

	// When loc is set (custom package), pkgWithDefault uses the location
	result = pkgWithDefault(loc, defaultPkg)
	fmt.Printf("Package name when loc is set: %s\n", result)
}

func pkgWithDefault(loc *codegen.Location, def string) string {
	if loc == nil {
		return def
	}
	return loc.PackageName()
}
